def solve(g):
    n=len(g); ps=valid_ps(g); p=ps[0]
    tor={}
    for i in range(n):
        for j in range(n):
            if g[i][j]: tor[(i%p,j%p)]=g[i][j]
    diag={}
    for (a,b),v in tor.items():
        diag[(b-a)%p]=v
    full={}
    for a in range(p):
        for b in range(p):
            full[(a,b)]=tor.get((a,b), diag[(b-a)%p])
    return [[full[(i%p,j%p)] for j in range(n)] for i in range(n)]
