    out=[]
    for p in range(1,n+1):
        tor={}; ok=True
        for i,j,v in cells:
            k=(i%p,j%p)
            if k in tor and tor[k]!=v: ok=False; break
            tor[k]=v
        if ok: out.append(p)
    return out

def transform(grid):
    g=grid; n=len(g)
    p=valid_ps(g)[0]
    tor={}
    for i in range(n):
        for j in range(n):
            if g[i][j]: tor[(i%p,j%p)]=g[i][j]
    diag={}
    for (a,b),v in tor.items(): diag[(b-a)%p]=v
    full={k:tor.get(k, diag[(k[1]-k[0])%p]) for k in [(a,b) for a in range(p) for b in range(p)]}
    return [[full[(i%p,j%p)] for j in range(n)] for i in range(n)]
